// Newton's method for F(X) = 0

// Initialize iterate
X = X0;
k = 0;

while (norm(F(X)) > tol && k < kmax) {
  // Build local linear model
  J = jacobian(F, X);

  // Solve for correction (Gauss / LU / QR — do NOT invert J)
  Delta = solve(J, -F(X));

  // Update iterate
  X = X + Delta;
  k = k + 1;
}

// Aitken's scheme — full 2D table

// Initialize: order-0 column = data y values
for (i = 0; i <= n; i++) dd[i][0] = y[i];

// Process: build successive orders from recursive definition
for (k = 1; k <= n; k++)
  for (i = 0; i <= n - k; i++)
    dd[i][k] = (dd[i + 1][k - 1] - dd[i][k - 1]) / (x[i + k] - x[i]);

// Return: top row holds the Newton form coefficients
//   dd[0][0], dd[0][1], ..., dd[0][n]

// Aitken's scheme — in place, one vector

// Initialize: y[i] starts holding the data values f(x_i)
// Process: each outer pass computes one higher divided-difference order
for (k = 1; k <= n; k++)
  // Sweep right-to-left so y[i-1] still holds the previous pass's value
  for (i = n; i >= k; i--)
    y[i] = (y[i] - y[i - 1]) / (x[i] - x[i - k]);

// Return: y[k] == [x_0, x_1, ..., x_k]_f for k = 0..n
//   These are exactly the Newton form coefficients.

